from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for serialized character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and basic shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize a scalar like the evaluator, converting scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length with binary-searched C-level slice comparisons."""
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute exact character-Trie reuse using sorted adjacent-string LCPs."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its row-specific source-column permutation."""
        return [
            "".join(cells[row, col] for col in orders[row])
            for row in range(cells.shape[0])
        ]

    @staticmethod
    def _value_counts(cells, rows, column):
        """Count serialized values in one column for a bounded row subset."""
        counts = {}
        for row in rows:
            value = cells[row, column]
            counts[value] = counts.get(value, 0) + 1
        return counts

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by length-weighted pair repetition with deterministic ties."""
        n, m = cells.shape
        ranked = []

        for col in range(m):
            counts = self._value_counts(cells, range(n), col)
            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            pairs = sum(count * (count - 1) for count in counts.values())

            if mode == 0:
                key = weighted
            else:
                key = weighted + pairs * max(
                    1, sum(len(v) for v in cells[:, col]) // max(1, n)
                )

            ranked.append((key, col))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [col for _, col in ranked]

    def _leaf_order(self, cells, rows, remaining) -> List[int]:
        """Rank a terminal suffix by local length-weighted value repetition."""
        ranked = []
        for col in remaining:
            counts = self._value_counts(cells, rows, col)
            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            ranked.append((score, col))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [col for _, col in ranked]

    def _prefix_conditional_orders(self, cells) -> List[List[int]]:
        """Recursively route rows through bounded shared-prefix buckets."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        result = [None] * n
        candidate_limit = min(16, m)

        def visit(rows, remaining, depth):
            """Choose a prefix-sharing leading field and recurse into its buckets."""
            if not remaining:
                for row in rows:
                    result[row] = []
                return

            if depth >= 3 or len(rows) < 3 or len(remaining) == 1:
                suffix = self._leaf_order(cells, rows, remaining)
                for row in rows:
                    result[row] = list(suffix)
                return

            field_scores = []
            for col in remaining:
                counts = self._value_counts(cells, rows, col)
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                field_scores.append((score, col))

            field_scores.sort(key=lambda item: (-item[0], item[1]))
            candidate_fields = [
                col for _, col in field_scores[:candidate_limit]
            ]

            best = None

            for col in candidate_fields:
                values = [(row, cells[row, col]) for row in rows]

                for width in (1, 2, 4):
                    buckets = {}
                    for row, value in values:
                        key = value[:width]
                        buckets.setdefault(key, []).append(row)

                    # Prefix collision mass estimates reusable characters.
                    collision = sum(
                        min(width, len(key)) * len(bucket) * (len(bucket) - 1)
                        for key, bucket in buckets.items()
                        if len(bucket) > 1
                    )

                    # Avoid pointless routing where all rows enter one bucket.
                    useful_split = len(buckets) > 1
                    choice = (
                        collision,
                        1 if useful_split else 0,
                        len(buckets),
                        -col,
                        -width,
                    )

                    if best is None or choice > best[0]:
                        best = (choice, col, buckets)

            if best is None or best[0][0] <= 0:
                suffix = self._leaf_order(cells, rows, remaining)
                for row in rows:
                    result[row] = list(suffix)
                return

            _, lead, buckets = best
            next_remaining = [
                col for col in remaining if col != lead
            ]

            for bucket_rows in buckets.values():
                visit(bucket_rows, next_remaining, depth + 1)

                # All rows in a bucket share the same recursively selected
                # suffix because routing decisions depend only on the bucket.
                suffix = result[bucket_rows[0]]
                for row in bucket_rows:
                    result[row] = [lead] + list(suffix)

        visit(list(range(n)), list(range(m)), 0)
        return result

    def _candidate(self, cells, orders):
        """Serialize, score exactly, and sort rows by serialized text."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global permutations and one recursive prefix-routed permutation."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for col in range(m):
                cells[row, col] = self._cell_text(raw[row, col])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        conditional = self._prefix_conditional_orders(cells)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-col for col in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, col] for col in source_order
            ]
            column_orders.append([
                df.columns[col] for col in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

